private bool ShouldSkip(CardModel card)
	{
		bool flag = card.Owner.Creature != base.Owner;
		bool flag2 = flag;
		if (!flag2)
		{
			bool flag3;
			switch (card.Pile?.Type)
			{
			case PileType.Hand:
			case PileType.Play:
				flag3 = true;
				break;
			default:
				flag3 = false;
				break;
			}
			flag2 = !flag3;
		}
		if (!flag2)
		{
			return GetInternalData<Data>().cardsPlayedThisTurn >= base.Amount;
		}
		return true;
	}

