                cases.Add(new{name,boundary=i==0?"prospective-root":"prospective-live",proof,productionIntegrated=false});
            }
        }
        Reject("invalid-local-cost-enum",new LocalCostModifier(1,(LocalCostType)999,LocalCostModifierExpiration.EndOfTurn,false),"unknown-cost-type");
        var harmony=new Harmony("combatsolver.testing.task-energy-cost-source");var prefix=typeof(UnattendedTestRunner).GetMethod(nameof(TaskEnergyUnknownPrefix),TaskLocalCostProof.Flags)!;
