        int rootCost=parent.State.GetPlayerCombatState(player).AllCards.Single(c=>c.References(card)).Preview.EnergyCost.GetWithModifiers(CostModifiers.Local);
        var children=Enumerable.Range(0,16).Select(_=>parent.Fork()).ToArray();var field=typeof(CardEnergyCost).GetField("_localModifiers",TaskLocalCostProof.Flags)!;object saved=field.GetValue(card.EnergyCost)!;
        var liveModifier=new LocalCostModifier(999,LocalCostType.Absolute,LocalCostModifierExpiration.EndOfTurn,false);
        field.SetValue(card.EnergyCost,new List<LocalCostModifier>{liveModifier});var frozenModifier=new LocalCostModifier(2,LocalCostType.Absolute,LocalCostModifierExpiration.EndOfTurn,false);var frozen=TaskLocalCostProof.Inspect(frozenModifier);frozenModifier.Amount=500;
