        finally{field.SetValue(card.EnergyCost,saved);}
        if(Stamp(parent)!=parentBefore||ContinuationStamp.CaptureLive(live).StateText!=liveBefore)throw new InvalidOperationException("Cost branches changed parent/live state/history/RNG.");
