                                int futureLoss = source.HpLostByTurn
                                    .Where(item => item.Key >= expectedTurn).Sum(item => item.Value);
                                int futureRecovery = source.HpRecoveredByTurn
                                    .Where(item => item.Key >= expectedTurn).Sum(item => item.Value);
                                if (pending.ProjectedBattleHpLost != 7 + futureLoss
